[{"order":1,"type":"heading","text":"Mastering Flutter Animations: Implicit vs Explicit Animations and AnimationController"},{"order":2,"type":"paragraph","text":"Animations are a crucial part of creating a polished, delightful user experience in Flutter. Understanding when to use implicit animations versus explicit animations is essential for building performant and maintainable applications."},{"order":3,"type":"subheading","text":"Implicit Animations: Simplicity First"},{"order":4,"type":"paragraph","text":"Implicit animations, also known as widget-based animations, manage their own internal animation state and controllers. You simply change a property (like width, color, or opacity), and the widget automatically animates from the old value to the new one."},{"order":5,"type":"bullet_point","text":"Pros: Extremely easy to implement with minimal boilerplate code."},{"order":6,"type":"bullet_point","text":"Cons: Limited control over the animation lifecycle (cannot easily pause, reverse mid-way, or chain complex sequences)."},{"order":7,"type":"code","text":"class ImplicitExample extends StatefulWidget {
  @override
  _ImplicitExampleState createState() => _ImplicitExampleState();
}

class _ImplicitExampleState extends State<ImplicitExample> {
  bool _isExpanded = false;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: () {
        setState(() {
          _isExpanded = !_isExpanded;
        });
      },
      child: AnimatedContainer(
        duration: Duration(milliseconds: 300),
        width: _isExpanded ? 200.0 : 100.0,
        height: _isExpanded ? 200.0 : 100.0,
        color: _isExpanded ? Colors.blue : Colors.red,
        curve: Curves.easeInOut,
      ),
    );
  }
}"},{"order":8,"type":"subheading","text":"Explicit Animations and AnimationController: Ultimate Control"},{"order":9,"type":"paragraph","text":"Explicit animations require you to explicitly manage the animation lifecycle using an AnimationController. This approach gives you absolute control over the animation progress, allowing you to play, pause, reverse, loop, or compose multiple animations together."},{"order":10,"type":"bullet_point","text":"AnimationController: Generates a new value between 0.0 and 1.0 for a given duration."},{"order":11,"type":"bullet_point","text":"TickerProviderStateMixin: Required by the AnimationController to hook into the screen refresh rate viavsync."},{"order":12,"type":"code","text":"class ExplicitExample extends StatefulWidget {
  @override
  _ExplicitExampleState createState() => _ExplicitExampleState();
}

class _ExplicitExampleState extends State<ExplicitExample> with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double> _animation;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      duration: Duration(seconds: 1),
      vsync: this,
    );
    _animation = Tween<double>(begin: 0.0, end: 300.0).animate(_controller);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: () {
        if (_controller.isCompleted) {
          _controller.reverse();
        } else {
          _controller.forward();
        }
      },
      child: AnimatedBuilder(
        animation: _animation,
        builder: (context, child) {
          return Container(
            width: _animation.value,
            height: 100.0,
            color: Colors.green,
          );
        },
      ),
    );
  }
}"},{"order":13,"type":"subheading","text":"Summary: When to use which?"},{"order":14,"type":"bullet_point","text":"Use Implicit Animations for standard UI state changes like fading out, resizing, or switching themes where fire-and-forget is sufficient."},{"order":15,"type":"bullet_point","text":"Use Explicit Animations and AnimationControllers for complex sequences, continuous looping animations, custom interactive physics, or when exact control over playback state is required."}]
